    return {'schema': 'yado.learned_recall_capability.v1', 'experience_digest': LEARNED_EXPERIENCE['experience_digest'], 'fact_count': len(LEARNED_EXPERIENCE['facts']), 'external_code_executed': False, 'canonical_active': False}
